class Solution {
  public boolean[] canEat(int[] candiesCount, int[][] queries) {
    long[] prefix = new long[candiesCount.length + 1];
    for (int i = 0; i < candiesCount.length; i++) prefix[i + 1] = prefix[i] + candiesCount[i];
    boolean[] ans = new boolean[queries.length];
    for (int i = 0; i < queries.length; i++) {
      int type = queries[i][0], day = queries[i][1], cap = queries[i][2];
      long minEaten = day + 1L, maxEaten = (day + 1L) * cap;
      ans[i] = maxEaten > prefix[type] && minEaten <= prefix[type + 1];
    }
    return ans;
  }
}
